# @title 🏆 Challenge Submission: Inferencia y Generación de CSVs

import csv
import numpy as np
from google.colab import files

# @param ["EfficientNet_B3 Solo", "DenseNet121 Solo", "Ensemble (Ambos)"]
SUBMISSION_MODE = "Ensemble (Ambos)"

CENTER_5_DIR = os.path.join(BASE_PATH, "center_5", "test", "png")
print(f"🔍 Preparando Submission para: {SUBMISSION_MODE}")

def parse_center_5(directory):
    all_files = glob.glob(os.path.join(directory, "*.png"))
    data_dict = {}

    for file_path in all_files:
        filename = os.path.basename(file_path)
        match = re.search(r"(P\d+_S\d+).*?(ADC|DWI)\.png", filename)

        if match:
            patient_slice = match.group(1)
            modality = match.group(2)

            if patient_slice not in data_dict:
                data_dict[patient_slice] = {'DWI': None, 'ADC': None}
            data_dict[patient_slice][modality] = file_path

    paired_data =[]
    for ps_id, info in data_dict.items():
        if info['DWI'] is not None and info['ADC'] is not None:
            paired_data.append({
                'id': ps_id,
                'dwi_path': info['DWI'],
                'adc_path': info['ADC'],
                'label': 0
            })

    return pd.DataFrame(paired_data)

test_c5_df = parse_center_5(CENTER_5_DIR)

if len(test_c5_df) > 0:
    test_c5_dataset = StrokeMultiModalDataset(test_c5_df, transform=val_transforms, numpy_base=BASE_PATH)
    test_c5_loader = DataLoader(test_c5_dataset, batch_size=BATCH_SIZE, shuffle=False)

    if SUBMISSION_MODE == "EfficientNet_B3 Solo":
        model_names = ["EfficientNet_B3"]
        csv_filename = "BIVL2ab_submission_DSA-FedProx_EffB3_TTA.csv"
    elif SUBMISSION_MODE == "DenseNet121 Solo":
        model_names = ["DenseNet121"]
        csv_filename = "BIVL2ab_submission_DSA-FedProx_Dense121_TTA.csv"
    else:
        model_names = ["DenseNet121", "EfficientNet_B3"]
        csv_filename = "BIVL2ab_submission_ENSEMBLE_DSA-FedProx_TTA.csv"

    ensemble_probs = np.zeros(len(test_c5_df))

    # Test-Time Augmentation
    tta_transforms = [
        lambda x: x,
        transforms.RandomHorizontalFlip(p=1.0),
        transforms.RandomRotation(degrees=[10, 10]),
        transforms.RandomRotation(degrees=[-10, -10])
    ]

    for m_name in model_names:
        print(f"\n🧠 Evaluando modelo: {m_name} con TTA...")

        # Buscamos el nombre correcto del archivo
        best_model_path = f'/content/best_federated_Similarity-FedProx_{m_name}.pth'

        if not os.path.exists(best_model_path):
            print(f"❌ ERROR: No se encontró {best_model_path}")
            continue

        model_inference = get_model(m_name).to(device)
        model_inference.load_state_dict(torch.load(best_model_path))
        model_inference.eval()

        model_probs = []

        with torch.no_grad():
            for i, (inputs, _) in enumerate(test_c5_loader):
                inputs = inputs.to(device)
                batch_probs = np.zeros((inputs.size(0), len(tta_transforms)))

                for t_idx, tta_trans in enumerate(tta_transforms):
                    inputs_aug = tta_trans(inputs)
                    outputs = model_inference(inputs_aug)
                    p = torch.sigmoid(outputs).cpu().numpy().flatten()

                    # PROTECCIÓN ANTI-NaN PARA LA INFERENCIA:
                    batch_probs[:, t_idx] = np.nan_to_num(p, nan=0.0)

                final_batch_probs = batch_probs.mean(axis=1)
                model_probs.extend(final_batch_probs)

        ensemble_probs += np.array(model_probs)

    final_ensemble_probs = ensemble_probs / len(model_names)

    results = []
    for slice_id, prob in zip(test_c5_df['id'].values, final_ensemble_probs):
        results.append([slice_id, prob])

    with open(csv_filename, mode='w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['Patient_Slice_ID', 'Stroke_Probability'])
        writer.writerows(results)

    print(f"\n🎉 ¡LISTO! CSV generado con éxito: {csv_filename}")
    files.download(csv_filename)
else:
    print("❌ No se encontraron imágenes en la ruta de Center 5.")